from collections import defaultdict

def topo_dfs(n, edges):
    g = defaultdict(list)
    for u, v in edges:
        g[u].append(v)
    state = [0] * n  # 0 unseen 1 active 2 done
    out = []
    ok = True

    def dfs(u):
        nonlocal ok
        state[u] = 1
        for v in g[u]:
            if state[v] == 1:
                ok = False
            elif state[v] == 0:
                dfs(v)
        state[u] = 2
        out.append(u)

    for u in range(n):
        if state[u] == 0:
            dfs(u)
    return list(reversed(out)) if ok else []
